    SimpleTimeZone zone = new SimpleTimeZone(tzoffset, tzid);
    Calendar cal = Calendar.getInstance((SimpleTimeZone) zone.clone());

    if (!zone.equals(cal.getTimeZone())) {
        fail("FAIL: Calendar.getTimeZone failed");
    }

