    });
    checkWMTE(() -> { // primitive class
        int x = (int) vh.getAndBitwiseXorRelease(true);
    });
    // Incorrect arity
    checkWMTE(() -> { // 0
        boolean x = (boolean) vh.getAndBitwiseXorRelease();
    });
    checkWMTE(() -> { // >
        boolean x = (boolean) vh.getAndBitwiseXorRelease(true, Void.class);
    });
}

