                              +"::<init>",
                          Constructor.class.getName()
                              +"::newInstanceWithCaller",
                          Constructor.class.getName()
                              +"::newInstance",
                          StackInspector.Caller.class.getName()
                              +"::create",
                          // MethodHandle::invoke remains hidden
                          StackInspector.Caller.class.getName()
                              +"::handle",
                          Method.class.getName()
                              +"::invoke",
                          ReflectionFrames.class.getName()
                              +"::testConstructor"));
