    // From: ABC-1123...890.012...789
    // To  : ABC-1.123...890.0123...789
    //          ~ : FieldPosition(DECIMAL_SEPARATOR)
    fp = new FieldPosition(NumberFormat.Field.DECIMAL_SEPARATOR);
    formatted = new StringBuffer("ABC");
    from = "-1"     + nonsep_int + "."  + fra;
