    nf.format(new BigDecimal(from), formatted, new FieldPosition(0));
    checkFormat(from, formatted, to, ((DecimalFormat)nf).getMultiplier());

    /* ------------------------------------------------------------------ */

    // From: -1234...78900000...0000.0...0
    // To:   -1,234...7,890,000,0...0,000.0...0
