static void testArrayWrongMethodType(VarHandle vh) throws Throwable {
    char[] array = new char[10];
    Arrays.fill(array, '\u0123');

    // Get
    // Incorrect argument types
    checkNPE(() -> { // null array
        char x = (char) vh.get(null, 0);
    });
