public void testAddPartitionEpochs() {
    Uuid fooTopicId = Uuid.randomUuid();
    ConsumerGroup consumerGroup = createConsumerGroup("foo");

    consumerGroup.addPartitionEpochs(
        mkAssignment(
            mkTopicAssignment(fooTopicId, 1)
        ),
