    );

    // Changing the epoch should fail because the owner of the partition
    // should remove it first.
    assertThrows(IllegalStateException.class, () -> consumerGroup.addPartitionEpochs(
        mkAssignment(
            mkTopicAssignment(fooTopicId, 1)
        ),
        11
    ));
}

