    addSubtypeConstraint(ctx, listType(superWild(a)), listType(extendsWild(b)));

    assertThat(b, hasBoundsExactly(upper(ts.OBJECT), lower(ts.OBJECT)));
    assertThat(a, hasBoundsExactly(upper(ts.OBJECT)));
}

